#!/usr/bin/env bash
# Deploy every dataset file the eval suite reads (coast_eval.datasets.PINS) into a
# dataset directory, e.g. a coastd daemon's dataset_base:
#
#   scripts/deploy_eval_data.sh <target-dir>
#
#   mnist/{train,t10k}-{images-idx3,labels-idx1}-ubyte   downloaded (.gz), unpacked
#   mnist_c/<corruption>/t10k-*                          generated by fetch_mnist_c.py
#                                                        from Zenodo's mnist_c.zip
#
# Every file is checked against its SHA256 pin before it takes its final name. A file
# that already matches its pin is left alone; a present file that does not match is
# refused, never overwritten. Ends by verifying all pins. Needs curl, gunzip, uv.
#
# The per-run eval inputs (train/test manifests, zeros image) are not deployed here:
# they depend on the run's image counts, and eval_ab.py writes and ships them itself.
set -euo pipefail

usage() { echo "usage: $0 <target-dir>" >&2; exit 2; }
[[ $# -eq 1 ]] || usage
target=$1
[[ -d "$target" ]] || { echo "$target: not a directory (create it first)" >&2; exit 1; }
target=$(cd "$target" && pwd)

scripts=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
eval_project="$scripts/../eval"
MIRROR=https://ossci-datasets.s3.amazonaws.com/mnist  # as in download_datasets.sh

# "<sha256> <relative path>" for the four MNIST files, from the one pin table.
mnist_pins=$(uv run --quiet --project "$eval_project" python -c '
from coast_eval import datasets as ds
for rel, sha in ds.PINS.items():
    if rel.startswith("mnist/"):
        print(sha, rel)')
[[ $(wc -l <<<"$mnist_pins") -eq 4 ]] || { echo "expected 4 MNIST pins, got: $mnist_pins" >&2; exit 1; }

while read -r sha rel; do
    path="$target/$rel"
    if [[ -e "$path" ]]; then
        have=$(sha256sum "$path" | cut -d' ' -f1)
        [[ "$have" == "$sha" ]] || {
            echo "$path: present but sha256 $have is not the pinned $sha; refusing to overwrite" >&2
            exit 1
        }
        echo "ok      $rel"
        continue
    fi
    mkdir -p "$(dirname "$path")"
    part="$path.part"
    curl --fail --silent --show-error --location -o "$part.gz" "$MIRROR/$(basename "$rel").gz"
    gunzip -c "$part.gz" >"$part"
    rm "$part.gz"
    have=$(sha256sum "$part" | cut -d' ' -f1)
    if [[ "$have" != "$sha" ]]; then
        rm "$part"
        echo "$rel: download has sha256 $have, not the pinned $sha" >&2
        exit 1
    fi
    mv "$part" "$path"
    echo "wrote   $rel"
done <<<"$mnist_pins"

uv run --quiet --script "$scripts/fetch_mnist_c.py" --data-root "$target"

uv run --quiet --project "$eval_project" python -c '
import sys
from pathlib import Path
from coast_eval import datasets as ds
ds.verify_pins(Path(sys.argv[1]), ds.PINS)
print(f"all {len(ds.PINS)} pinned eval files under {sys.argv[1]} match their pins")' "$target"
